select 'young' as cohort, round(avg(A11)) as avg_salary from district where district_id in (select a.district_id from account a join disp p on p.account_id=a.account_id join client c on c.client_id=p.client_id where c.birth_date>='1980-01-01')
union all
select 'old', round(avg(A11)) from district where district_id in (select a.district_id from account a join disp p on p.account_id=a.account_id join client c on c.client_id=p.client_id where c.birth_date<='1919-12-31');
